static void lcd_data(const void *p, uint32_t n)
{
    if (!n)
        return;                    /* SPI_CNT = 0 never completes */
    lcd_sync();
    fm1_lcd_send_data(p, n);
    lcd_busy = 1;                  /* completed by lcd_sync */
}

static void lcd_window(uint32_t x0, uint32_t y0, uint32_t x1, uint32_t y1)
{
    lcd_sync();
    lcd_small[0] = (uint8_t)(x0 >> 8);
    lcd_small[1] = (uint8_t)x0;
    lcd_small[2] = (uint8_t)(x1 >> 8);
    lcd_small[3] = (uint8_t)x1;
    lcd_cmd(0x2A);
    lcd_data(lcd_small, 4);
    lcd_small[4] = (uint8_t)(y0 >> 8);       /* own bytes: the x transfer may still read [0..3] */
    lcd_small[5] = (uint8_t)y0;
    lcd_small[6] = (uint8_t)(y1 >> 8);
    lcd_small[7] = (uint8_t)y1;
    lcd_cmd(0x2B);
    lcd_data(lcd_small + 4, 4);
    lcd_cmd(0x2C);
}

static void fm1__p33_op(uint32_t op, uint32_t a, uint8_t d)   /* 0 wr, 1 or, 2 and, 3 xor */
{
    fm1__p33_cs(a);
    fm1__p33_xfer((uint8_t)((op << 5) | ((a >> 8) & 3u)));
    fm1__p33_xfer((uint8_t)a);
    fm1__p33_xfer(d);
    FM1_P33_CON &= ~((1u << 0) | (1u << 8));
}

uint8_t touch_vel(uint32_t key)
{
    if (key >= NKEYS)
        return 0;
    if (!sense_is_analog(key) && touch_live) {
        uint8_t v = sense_probe_velocity(key);
        if (v)
            touch_v[key] = v;
    }
    return touch_v[key] ? touch_v[key] : 100u;
}

/* app.c app_frame (the main loop): sending what's queued, the voice's name, and the whole screen for a new viewer
 * (or, after segments were dropped, what's missing: at most five times a second) */
void bs_service(void)
{
    static char name[24];
    uint32_t now = plat_ms();
    sm_poll(now, bs_send);
    bs_panel_service(now);
    if (sm_on()) {
        const char *v = TONE_NAME[set.tone & 3];
        uint32_t i = 0, k;
        for (k = 0; "ERIK37 "[k]; k++)
            name[i++] = "ERIK37 "[k];
        for (k = 0; v[k] && i < sizeof name - 1u; k++)
            name[i++] = v[k];
        name[i] = 0;
        sm_name(name, now, bs_send);
    }
    if (sm_take_full_request() | bs_new) {      /* a new viewer: it has nothing yet */
        uint32_t k;
        for (k = 0; k < 240u * BS_NSEG; k++)
            bs_hash[k / BS_NSEG][k % BS_NSEG] = 0;
        bs_new = 0;
        bs_redo = 1;
        bs_redo_at = now - 1000u;
    }
    if (bs_redo && sm_on() && ui.state == ST_RUN && now - bs_redo_at >= 200u) {
        bs_redo = 0;                             /* every band again: what the viewer has is skipped */
        bs_redo_at = now;
        ui.full = 1;
    }
}

/* the case, legs, lyre and keyboard (boot.py build) */
static void build(int mirror)
{
    rgb_t L = LACQ1;
    static const float LEG[3][2] = {{0.07f, 0.06f}, {0.07f, BD - 0.06f}, {0.83f, BD * 0.83f}};
    int i, k;
    float lz = BD * 0.5f, kx0 = -0.12f, kx1 = 0.0f, ky = 0.37f, zs0 = 0.035f, zs1 = BD - 0.035f;
    for (i = 0; i < 3; i++) {
        float lx = LEG[i][0], z = LEG[i][1], w = 0.022f, dl = depth_of(V(lx, 0.15f, z), mirror) + 0.05f;
        v3 n = {-0.3f, 0, -1};
        quad(V(lx - w, Y_CASE0, z), V(lx + w, Y_CASE0, z), V(lx + w * 0.6f, 0, z), V(lx - w * 0.6f, 0, z),
             shade(n, C3(15, 15, 18), 0.8f, 7), mirror, dl, 1);
        quad(V(lx - w, Y_CASE0, z), V(lx - w * 0.55f, Y_CASE0, z), V(lx - w * 0.35f, 0, z), V(lx - w * 0.6f, 0, z),
             C3(38, 38, 44), mirror, dl - 0.001f, 1);
        quad(V(lx - w * 0.9f, 0, z), V(lx + w * 0.9f, 0, z), V(lx + w * 0.9f, 0.012f, z), V(lx - w * 0.9f, 0.012f, z),
             GOLD_DIM, mirror, dl - 0.002f, 1);
    }
    for (k = 0; k < 2; k++) {
        float dx = k ? 0.018f : -0.018f;
        quad(V(0.16f + dx - 0.005f, Y_CASE0, lz), V(0.16f + dx + 0.005f, Y_CASE0, lz), V(0.16f + dx + 0.005f, 0.05f, lz),
             V(0.16f + dx - 0.005f, 0.05f, lz), C3(30, 30, 35), mirror, depth_of(V(0.16f, 0.1f, lz), mirror) + 0.02f, 1);
    }
    quad(V(0.12f, 0.05f, lz - 0.05f), V(0.20f, 0.05f, lz - 0.05f), V(0.20f, 0.025f, lz - 0.05f), V(0.12f, 0.025f, lz - 0.05f),
         C3(30, 30, 34), mirror, depth_of(V(0.16f, 0.04f, lz), mirror) + 0.01f, 1);
    for (k = 0; k < 3; k++) {
        float px = 0.135f + k * 0.025f;
        quad(V(px - 0.007f, 0.03f, lz - 0.11f), V(px + 0.007f, 0.03f, lz - 0.11f), V(px + 0.007f, 0.024f, lz - 0.05f),
             V(px - 0.007f, 0.024f, lz - 0.05f), GOLD, mirror, depth_of(V(px, 0.03f, lz - 0.08f), mirror), 1);
    }
    for (i = 0; i < NPLAN; i++) {              /* the case's sides turned to us */
        float x0 = plan[i][0], z0 = plan[i][1], x1 = plan[(i + 1) % NPLAN][0], z1 = plan[(i + 1) % NPLAN][1];
        v3 n = {z1 - z0, 0, -(x1 - x0)};
        float ov = 0.002f;
        if (!facing(n))
            continue;
        quad(V(x0 - ov * (x1 - x0), Y_CASE0, z0), V(x1, Y_CASE0, z1), V(x1, Y_CASE1, z1), V(x0, Y_CASE1, z0),
             shade(n, L, 1.0f, 7), mirror, 0, 0);
    }
    {
        v3 n = {-1, 0, 0};
        quad(V(kx0, ky - 0.035f, zs0), V(kx0, ky - 0.035f, zs1), V(kx0, ky, zs1), V(kx0, ky, zs0), shade(n, L, 1, 7), mirror, 0, 0);
    }
    quad(V(kx0, ky, zs0), V(kx1, ky, zs0), V(kx1, ky, zs1), V(kx0, ky, zs1), mixc(IVORY_DIM, IVORY, 0.3f), mirror, 0, 0);
    for (k = 0; k < 26; k++) {                 /* the black keys */
        float z = zs0 + (zs1 - zs0) * k / 26.0f;
        int m = k % 7;
        if (m == 0 || m == 1 || m == 3 || m == 4 || m == 5) {
            float zz = z + (zs1 - zs0) / 26.0f * 0.7f;
            quad(V(kx0 + 0.05f, ky + 0.002f, zz), V(kx1, ky + 0.002f, zz), V(kx1, ky + 0.002f, zz + 0.012f),
                 V(kx0 + 0.05f, ky + 0.002f, zz + 0.012f), C3(14, 14, 16), mirror, -10, 1);
        }
    }
    for (k = 0; k < 2; k++) {                  /* the cheeks */
        float zc = k ? zs1 : zs0 - 0.035f, d = depth_of(V(kx0, ky, zc), mirror) - 1;
        v3 n1 = {0, 0, -1}, n2 = {-1, 0, 0};
        quad(V(kx0 - 0.005f, Y_CASE0 + 0.02f, zc), V(kx1, Y_CASE0 + 0.02f, zc), V(kx1, Y_CASE1, zc),
             V(kx0 - 0.005f, Y_CASE1 - 0.03f, zc), shade(n1, L, 1, 7), mirror, d, 1);
        quad(V(kx0 - 0.005f, Y_CASE0 + 0.02f, zc + 0.035f), V(kx0 - 0.005f, Y_CASE0 + 0.02f, zc),
             V(kx0 - 0.005f, Y_CASE1 - 0.03f, zc), V(kx0 - 0.005f, Y_CASE1 - 0.03f, zc + 0.035f), shade(n2, L, 1, 7), mirror, d, 1);
    }
    {
        v3 n = {-1, 0, 0};
        quad(V(kx0, Y_CASE0 + 0.02f, zs0), V(kx0, Y_CASE0 + 0.02f, zs1), V(kx0, ky - 0.035f, zs1), V(kx0, ky - 0.035f, zs0),
             shade(n, L, 1, 7), mirror, -5, 1);
    }
}

static void mask_clear(int x0, int y0, int x1, int y1)
{
    int y;
    x0 = x0 < 0 ? 0 : x0;
    y0 = y0 < 0 ? 0 : y0;
    x1 = x1 > SW ? SW : x1;
    y1 = y1 > SH ? SH : y1;
    mbox.x0 = x0;
    mbox.y0 = y0;
    mbox.x1 = x1 > x0 ? x1 : x0;
    mbox.y1 = y1 > y0 ? y1 : y0;
    for (y = y0; y < y1; y++)
        memset(MASK + y * SW + x0, 0, (uint32_t)(x1 > x0 ? x1 - x0 : 0));
}

static void rect(int x0, int y0, int x1, int y1, rgb_t c, int a)   /* [x0, x1) x [y0, y1) */
{
    int x, y;
    for (y = y0; y < y1; y++)
        for (x = x0; x < x1; x++)
            blend(x, y, c, a);
}

static int panel_valid(const panel_t *p)
{
    uint32_t i, ok = p->magic == PANEL_MAGIC;
    for (i = 0; ok && i < NB; i++)
        ok = p->btn[i] < PANEL_NBTN;
    for (i = 0; ok && i < NE; i++)
        ok = p->enc[i] < PANEL_NENC && (p->dir[i] == 1 || p->dir[i] == -1);
    return (int)ok;
}

/* a readout for development over USB-MIDI: F0 7D 4C 47 F7 ("LG") asks; the answer is one frame per line,
 * F0 7D 4C 47 <ASCII> F7: the last crash (count, vector, pc, rets, sp, uptime), then Bluetooth's log, the oldest
 * first (it survives a reset) */
static void log_line_send(const char *t)
{
    uint8_t f[48];
    uint32_t n = 0;
    f[n++] = 0xF0; f[n++] = 0x7D; f[n++] = 0x4C; f[n++] = 0x47;
    while (*t && n < sizeof f - 1u)
        f[n++] = (uint8_t)(*t++ & 0x7Fu);
    f[n++] = 0xF7;
    ota_wire_send(f, n);
}
